#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    vector<int> res;
    for (int i = n-y; i < n; i++) res.push_back(p[i]);
    for (int i = x; i < n-y; i++) res.push_back(p[i]);
    for (int i = 0; i < x; i++) res.push_back(p[i]);
    p = res;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-1; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Move element from pos to n-1
        if(pos != n-1){
            if(pos <= n-3){
                // x=pos+1, y=1
                ops.push_back({pos+1, 1});
                apply_op(p, pos+1, 1);
            } else {
                // pos == n-2, use x=1,y=1: maps pos=n-2 via middle: n-2-1+1=n-2... 
                // Actually try brute force for this single step
                for(int x=1;x<n;x++) for(int y=1;x+y<n;y++){
                    // Check if this maps pos to n-1
                    int newpos;
                    if(pos >= n-y) newpos = pos-(n-y);
                    else if(pos >= x) newpos = pos-x+y;
                    else newpos = pos+(n-x);
                    if(newpos == n-1){ ops.push_back({x,y}); apply_op(p,x,y); goto moved; }
                }
                moved:;
            }
            pos = n-1;
        }

        if(pos == placed) continue;

        // Move element from n-1 to placed
        // y = placed+1, x=1
        int y = placed+1, x=1;
        if(x+y < n){
            ops.push_back({x, y});
            apply_op(p, x, y);
        } else {
            for(int xx=1;xx<n;xx++) for(int yy=1;xx+yy<n;yy++){
                int np; int pp=n-1;
                if(pp>=n-yy) np=pp-(n-yy); else if(pp>=xx) np=pp-xx+yy; else np=pp+(n-xx);
                if(np==placed){ops.push_back({xx,yy});apply_op(p,xx,yy);goto moved2;}
            }
            moved2:;
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
